// The page says "Payment failed, try again",
// and the second click charges the card again

public enum Outcome { Paid, Rejected, Unknown }

public sealed class Checkout(HttpClient http, ILogger<Checkout> log)
{
    public async Task<Outcome> PayAsync(Charge charge, CancellationToken ct)
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(TimeSpan.FromSeconds(3)); // a deadline for this call
        try
        {
            var res = await http.PostAsJsonAsync("/charges", charge, cts.Token);
            if (res.IsSuccessStatusCode) return Outcome.Paid;
            // 4xx: Payments answered no. 5xx: it may have done part of it
            return (int)res.StatusCode < 500 ? Outcome.Rejected : Outcome.Unknown;
        }
        catch (Exception e) when (e is HttpRequestException
                                     or OperationCanceledException)
        {
            // No answer isn't a "no": ask Payments about charge.Id first
            log.LogWarning(e, "Charge {ChargeId} outcome unknown", charge.Id);
            return Outcome.Unknown;
        }
    }
}
